import{_ as r,o,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"历史记录","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/history.md","filePath":"zh-CN/user-guide/settings/history.md","lastUpdated":1787586465000}'),n={name:"zh-CN/user-guide/settings/history.md"};function a(i,t,l,g,d,c){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="历史记录" tabindex="-1">历史记录 <a class="header-anchor" href="#历史记录" aria-label="Permalink to &quot;历史记录&quot;">​</a></h1><p>历史记录页面用于管理 Lertaro 的使用痕迹与智能推荐权重。页面顶部包含两个相互独立的标签页：<strong>搜索记录</strong>与<strong>关键字记录</strong>。</p><h2 id="_1-搜索记录-search-history" tabindex="-1">1. 搜索记录（Search History） <a class="header-anchor" href="#_1-搜索记录-search-history" aria-label="Permalink to &quot;1. 搜索记录（Search History）&quot;">​</a></h2><p>搜索记录追踪你实际点击或回车打开过的搜索结果，并将打开时的“搜索关键词”与“目标物理路径”进行双向绑定学习：</p><ul><li><strong>智能优先召回</strong>：当你之后输入与先前查询相似或模糊相关的字符时，Lertaro 会自动在结果列表前列优先召回该文件。例如，你曾通过输入 <code>bcomp</code> 打开过 <code>BCompare.exe</code>，未来只需输入 <code>bc</code>，该程序依然会被优先推至前排。</li><li><strong>内嵌窗口智能分区</strong>：在文件选择对话框的内嵌搜索中，历史匹配项若属于当前文件夹内，会自动归入“当前文件夹”分组，其余则归入“全局搜索”分组。</li><li><strong>失效路径自动过滤</strong>：若已记录的文件或目录被外部删除或移动，Lertaro 在检索时会自动过滤不存在的死链，且相同路径在列表中绝不重复显示。</li><li><strong>管理操作</strong>： <ul><li><strong>启用历史记录</strong>：总开关，关闭后保留现有数据但不再记录新的打开行为。</li><li><strong>搜索过滤</strong>：在上方搜索框输入关键词快速定位特定历史条目。</li><li><strong>单条删除与一键清空</strong>：每行配有删除按钮，亦可点击<strong>清空全部记录</strong>重置所有打开记录。</li></ul></li></ul><h2 id="_2-关键字记录-keyword-history" tabindex="-1">2. 关键字记录（Keyword History） <a class="header-anchor" href="#_2-关键字记录-keyword-history" aria-label="Permalink to &quot;2. 关键字记录（Keyword History）&quot;">​</a></h2><p>关键字记录专门用于记忆你在快速搜索窗口中键入过的<strong>原始查询字符串</strong>（无论是否最终打开了文件）：</p><ul><li><strong>热键快速翻阅</strong>：在快速搜索窗口中，可使用快捷键 <strong><code>Alt+Up</code></strong> 向前翻阅、<strong><code>Alt+Down</code></strong> 向后翻阅最近输入过的搜索词；按下 <strong><code>Ctrl+Delete</code></strong> 即可从记录中直接删除当前显示的这条词汇。</li><li><strong>独立控制与维护</strong>：与搜索记录一样提供专属的<strong>启用历史记录</strong>开关、关键词搜索过滤、单条删除与<strong>清空全部记录</strong>按钮。</li></ul>',8)])])}const u=r(n,[["render",a]]);export{_ as __pageData,u as default};
